// The checks of the school form (Add / Edit school), kept apart so they can be tested on their own. A school that came back from the
// server without some fields (for example no currency or mobile number) has them undefined or null, which counts as "not filled in"
// - the form must show the message, never fail. Language and fax are optional.
const missing = value => value === undefined || value === null || String(value).trim() === '';

export const schoolFormErrors = data => {
  const errors = {};
  if (missing(data.schoolCode)) errors.schoolCode = 'School code cannot be empty';
  if (missing(data.schoolName)) errors.schoolName = 'School name cannot be empty';
  if (missing(data.schoolShortName)) errors.schoolShortName = 'School short name cannot be empty';
  if (missing(data.address)) errors.address = 'Address cannot be empty';
  if (missing(data.mobileNumber)) errors.mobileNumber = 'Mobile number cannot be empty';
  if (missing(data.country)) errors.country = 'Country cannot be empty';
  if (missing(data.currencyType)) errors.currencyType = 'Currency type cannot be empty';
  return errors;
};
